cell get_data() asm "c4 PUSH";
() set_data(cell c) impure asm "c4 POP";
slice begin_parse(cell c) asm "CTOS";
builder begin_cell() asm "NEWC";
cell end_cell(builder b) asm "ENDC";
int slice_empty?(slice s) asm "SEMPTY";

global int ctr;
int load_data() inline { var ds = get_data().begin_parse(); return ds~load_uint(64); }
() save_data(int x) impure inline_ref { set_data(begin_cell().store_uint(x, 64).end_cell()); }
() recv_internal(int msg_value, cell in_msg, slice in_msg_body) impure {
  if (in_msg_body.slice_empty?()) { return (); }
  int op = in_msg_body~load_uint(32);
  ctr = load_data();
  if (op == 1) { save_data(ctr + 1); return (); }
  throw(0xffff);
}
int counter() method_id { return load_data(); }

